import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import AdminDashboard from './components/Admin/AdminDashboard';
import HomePage from './components/User/HomePage';
import CheckoutPage from './components/User/CheckoutPage';
import ThankYouPage from './components/User/ThankYouPage';
import { INITIAL_MENU, INITIAL_TABLES, INITIAL_ORDERS, INITIAL_CHEFS } from './mockData';
import './App.css';

function App() {
  // --- Central State Management ---
  const [menuItems, setMenuItems] = useState(INITIAL_MENU);
  const [tables, setTables] = useState(INITIAL_TABLES);
  const [orders, setOrders] = useState(INITIAL_ORDERS);
  const [cart, setCart] = useState([]);
  const [chefs, setChefs] = useState(INITIAL_CHEFS); 
  
  // NEW STATE: Control the initial details modal
  const [isModalOpen, setIsModalOpen] = useState(true);

